import { useState, useEffect, useRef, useCallback } from 'react';
import AnalogClock from './components/AnalogClock';
import ClockControls from './components/ClockControls';
import { ClockSettings, ClockHandAngles } from './types';

const INITIAL_SETTINGS: ClockSettings = {
  theme: 'classic',
  smoothSeconds: true,
  showDigital: true,
  showDate: true,
  showTicks: true,
  isPaused: false,
};

const JAPANESE_WEEKDAYS = ['日曜日', '月曜日', '火曜日', '水曜日', '木曜日', '金曜日', '土曜日'];

export default function App() {
  const [settings, setSettings] = useState<ClockSettings>(INITIAL_SETTINGS);

  // 表示用時刻（Dateインスタンス）
  const [currentTime, setCurrentTime] = useState<Date>(() => new Date());

  // アニメーションフレーム制御用Ref
  const animFrameIdRef = useRef<number | null>(null);
  const pausedTimeRef = useRef<Date | null>(null);
  const timeOffsetRef = useRef<number>(0);

  // 各針の角度を計算
  const angles: ClockHandAngles = {
    hours:
      ((currentTime.getHours() % 12) +
        currentTime.getMinutes() / 60 +
        currentTime.getSeconds() / 3600) *
      30,
    minutes:
      (currentTime.getMinutes() +
        currentTime.getSeconds() / 60 +
        currentTime.getMilliseconds() / 60000) *
      6,
    seconds: currentTime.getSeconds(),
    milliseconds: currentTime.getMilliseconds(),
  };

  // 時計更新ループ
  useEffect(() => {
    if (settings.isPaused) {
      if (animFrameIdRef.current) {
        cancelAnimationFrame(animFrameIdRef.current);
        animFrameIdRef.current = null;
      }
      return;
    }

    const updateClock = () => {
      const now = new Date(Date.now() - timeOffsetRef.current);
      setCurrentTime(now);
      animFrameIdRef.current = requestAnimationFrame(updateClock);
    };

    animFrameIdRef.current = requestAnimationFrame(updateClock);

    return () => {
      if (animFrameIdRef.current) {
        cancelAnimationFrame(animFrameIdRef.current);
      }
    };
  }, [settings.isPaused]);

  // 設定の更新
  const handleUpdateSettings = useCallback((newSettings: Partial<ClockSettings>) => {
    setSettings((prev) => ({ ...prev, ...newSettings }));
  }, []);

  // 一時停止 / 再開の切り替え
  const handleTogglePause = useCallback(() => {
    setSettings((prev) => {
      const willPause = !prev.isPaused;
      if (willPause) {
        pausedTimeRef.current = new Date();
      } else if (pausedTimeRef.current) {
        // 停止していた時間差をオフセットに加算
        const pauseDuration = Date.now() - pausedTimeRef.current.getTime();
        timeOffsetRef.current += pauseDuration;
        pausedTimeRef.current = null;
      }
      return { ...prev, isPaused: willPause };
    });
  }, []);

  // 現在時刻に再同期
  const handleResetToCurrentTime = useCallback(() => {
    timeOffsetRef.current = 0;
    pausedTimeRef.current = null;
    const now = new Date();
    setCurrentTime(now);
    if (settings.isPaused) {
      setSettings((prev) => ({ ...prev, isPaused: false }));
    }
  }, [settings.isPaused]);

  // デジタル時刻フォーマット
  const hoursStr = String(currentTime.getHours()).padStart(2, '0');
  const minutesStr = String(currentTime.getMinutes()).padStart(2, '0');
  const secondsStr = String(currentTime.getSeconds()).padStart(2, '0');
  const digitalTimeText = `${hoursStr}:${minutesStr}:${secondsStr}`;

  // 日付フォーマット
  const year = currentTime.getFullYear();
  const month = currentTime.getMonth() + 1;
  const day = currentTime.getDate();
  const weekday = JAPANESE_WEEKDAYS[currentTime.getDay()];
  const digitalDateText = `${year}年${month}月${day}日 (${weekday})`;

  // テーマクラス決定
  const themeClass = `theme-${settings.theme}`;

  return (
    <main className={`app-wrapper ${themeClass}`}>
      {/* アナログ時計盤面 */}
      <AnalogClock angles={angles} settings={settings} />

      {/* デジタル時計＆日付表示 */}
      {(settings.showDigital || settings.showDate) && (
        <section className="digital-display" aria-live="off">
          {settings.showDigital && (
            <time className="digital-time" dateTime={currentTime.toISOString()}>
              {digitalTimeText}
            </time>
          )}
          {settings.showDate && (
            <span className="digital-date">{digitalDateText}</span>
          )}
        </section>
      )}

      {/* コントロールパネル */}
      <ClockControls
        settings={settings}
        onUpdateSettings={handleUpdateSettings}
        onResetToCurrentTime={handleResetToCurrentTime}
        isPaused={settings.isPaused}
        onTogglePause={handleTogglePause}
      />

      {/* 操作説明ノート */}
      <p className="info-note">
        60fpsで滑らかに回転する精密スイープ秒針と、カチカチと動くステップ運針をリアルタイムに切り替え可能。
        4種類の洗練されたカラーテーマや一時停止機能をお試しください。
      </p>
    </main>
  );
}
